//! Parse only directives and operands generated by `native::emit`.

use super::{
    Error,
    Item,
    Kind,
    Object,
    Result,
    encoder,
};
use crate::util::bump::{
    ArenaMap,
    ArenaVec,
    Bump,
};

pub(super) fn parse<'a>(text: &'a str, arena: &'a Bump) -> Result<Object<'a>> {
    let mut object = Object {
        arena,
        coff: false,
        sections: ArenaVec::new_in(arena),
        symbols: ArenaVec::new_in(arena),
        names: ArenaMap::with_hasher_in(rustc_hash::FxBuildHasher, arena),
        items: ArenaVec::new_in(arena),
    };
    let mut section = object.section(".text", 1, 6, None)?;
    for line in text.lines().map(str::trim).filter(|line| !line.is_empty()) {
        let kind = if let Some(name) = line.strip_suffix(':') {
            symbol_name(name)?;
            let id = object.symbol(name);
            if object.symbols[id].section.is_some() || object.symbols[id].alias.is_some() {
                return Err(Error("duplicate label or symbol definition"));
            }
            object.symbols[id].section = Some(section);
            Kind::Label(id)
        } else if let Some((name, target)) = assignment(line) {
            symbol_name(name)?;
            symbol_name(target)?;
            let id = object.symbol(name);
            if object.symbols[id].section.is_some() || object.symbols[id].alias.is_some() {
                return Err(Error("duplicate symbol definition"));
            }
            object.symbols[id].alias = Some(object.symbol(target));
            continue;
        } else {
            let (name, args) = line
                .split_once(char::is_whitespace)
                .map_or((line, ""), |(a, b)| (a, b.trim()));
            directive_operands(name, args)?;
            let mut parts = split(args);
            let first = parts.next().unwrap_or("");
            match name {
                | ".text" | ".data" | ".bss" => {
                    section = object.section(
                        name,
                        if name == ".bss" { 8 } else { 1 },
                        if name == ".text" { 6 } else { 3 },
                        None,
                    )?;
                    continue;
                },
                | ".section" => {
                    let name = unquote(first);
                    if name.is_empty()
                        || !name.bytes().all(|b| {
                            b.is_ascii_alphanumeric() || matches!(b, b'_' | b'.' | b'$' | b'-')
                        })
                    {
                        return Err(Error("unsupported section name"));
                    }
                    let (default_kind, default_flags) = section_defaults(name);
                    let flags = parts.next().map_or("", unquote);
                    let flags = flags.bytes().try_fold(default_flags, |bits, ch| {
                        Ok(bits
                            | match ch {
                                | b'a' => 2,
                                | b'w' => 1,
                                | b'x' => 4,
                                | b'T' => 0x400,
                                | b'G' => 0x200,
                                | b'l' => 0x1000_0000,
                                | _ => return Err(Error("unknown section flag")),
                            })
                    })?;
                    let explicit_kind = parts.next();
                    let mut kind = match explicit_kind {
                        | None => default_kind,
                        | Some("@progbits") => 1,
                        | Some("@nobits") => 8,
                        | Some("@note") => 7,
                        | Some("@init_array") => 14,
                        | Some("@fini_array") => 15,
                        | Some("@preinit_array") => 16,
                        | _ => return Err(Error("unknown section type")),
                    };
                    if matches!(name, ".eh_frame" | ".gcc_except_table") && flags != 2 {
                        return Err(Error("unsupported reserved section flags"));
                    }
                    let group = if flags & 0x200 != 0 {
                        let signature = parts.next().ok_or(Error("missing COMDAT signature"))?;
                        symbol_name(signature)?;
                        let symbol = object.symbol(signature);
                        if parts.next() != Some("comdat") {
                            return Err(Error("unknown group selection"));
                        }
                        Some(symbol)
                    } else {
                        None
                    };
                    if parts.next().is_some() {
                        return Err(Error("unsupported section arguments"));
                    }
                    if explicit_kind.is_none()
                        && let Some(existing) = object
                            .sections
                            .iter()
                            .find(|s| s.name == name && s.group == group)
                    {
                        kind = existing.kind;
                    }
                    section = object.section(name, kind, flags, group)?;
                    continue;
                },
                | ".globl" | ".weak" | ".hidden" | ".protected" | ".type" => {
                    symbol_name(first)?;
                    let id = object.symbol(first);
                    let symbol = &mut object.symbols[id];
                    if symbol.name.starts_with(".L") {
                        return Err(Error("unsupported temporary symbol attributes"));
                    }
                    match name {
                        | ".globl" =>
                            if symbol.binding == 2 {
                                return Err(Error("global binding after weak binding"));
                            } else {
                                symbol.binding = 1;
                            },
                        | ".weak" => symbol.binding = 2,
                        | ".hidden" | ".protected" => {
                            let visibility = if name == ".hidden" { 2 } else { 3 };
                            if symbol.visibility != 0 && symbol.visibility != visibility {
                                return Err(Error("conflicting symbol visibility"));
                            }
                            symbol.visibility = visibility;
                        },
                        | _ => {
                            let kind = match parts.next() {
                                | Some("@function") => 2,
                                | Some("@object") => 1,
                                | _ => return Err(Error("unknown symbol type")),
                            };
                            if symbol.kind != 0 && symbol.kind != kind {
                                return Err(Error("conflicting symbol type"));
                            }
                            symbol.kind = kind;
                        },
                    }
                    continue;
                },
                // ELF gABI "Symbol Table": `SHN_COMMON` holds the
                // alignment as the value.
                | ".comm" => {
                    symbol_name(first)?;
                    let size = unsigned(parts.next().ok_or(Error("missing common size"))?)?;
                    let align = unsigned(parts.next().ok_or(Error("missing common alignment"))?)?;
                    let id = object.symbol(first);
                    let symbol = &mut object.symbols[id];
                    if symbol.section.is_some() || symbol.alias.is_some() || symbol.common {
                        return Err(Error("duplicate common symbol definition"));
                    }
                    if symbol.binding == 0 {
                        symbol.binding = 1;
                    }
                    symbol.common = true;
                    symbol.kind = 1;
                    symbol.value = align;
                    symbol.size = size;
                    continue;
                },
                | ".size" => {
                    symbol_name(first)?;
                    let id = object.symbol(first);
                    let size = parts.next().ok_or(Error("missing symbol size"))?;
                    Kind::Size(
                        id,
                        if let Some(base) = size.strip_prefix(".-") {
                            if unquote(base) != unquote(first)
                                || object.symbols[id].section != Some(section)
                            {
                                return Err(Error("unsupported symbol size expression"));
                            }
                            None
                        } else {
                            Some(unsigned(size)?)
                        },
                    )
                },
                | ".p2align" => {
                    let (align, fill, max) = alignment(first, &mut parts, 1 << 30)?;
                    object.sections[section].align = object.sections[section].align.max(align);
                    Kind::Align { align, fill, max }
                },
                | ".zero" => Kind::Zero(unsigned(first)?),
                | ".byte" | ".short" | ".long" | ".quad" => {
                    let width = match name {
                        | ".byte" => 1,
                        | ".short" => 2,
                        | ".long" => 4,
                        | _ => 8,
                    };
                    for part in split(args) {
                        object.items.push(Item {
                            section,
                            offset: 0,
                            kind: Kind::Value(width, part),
                        });
                    }
                    continue;
                },
                | name if name.starts_with(".cfi_") => Kind::Cfi(name, args),
                | name if name.starts_with('.') => return Err(Error("unknown object directive")),
                | "jmp" => {
                    symbol_name(args)?;
                    Kind::Branch {
                        condition: None,
                        target:    object.symbol(args),
                        near:      false,
                    }
                },
                | name if name.starts_with('j') && name != "jmpq" => {
                    symbol_name(args)?;
                    Kind::Branch {
                        condition: Some(encoder::condition(&name[1..])?),
                        target:    object.symbol(args),
                        near:      false,
                    }
                },
                | _ => Kind::Code(encoder::instruction(name, args)?),
            }
        };
        object.items.push(Item {
            section,
            offset: 0,
            kind,
        });
    }
    Ok(object)
}

/// The operands of `.p2align align[, [fill][, max]]`, after the power of
/// two `first`, as MC reads them for ELF and COFF alike: the alignment in
/// bytes (at most `limit`), the fill byte (none pads code with `nop`s) and
/// the most padding to emit. A maximum below one is an error in MC; one of
/// at least the alignment has no effect.
pub(super) fn alignment<'t>(
    first: &str,
    parts: &mut impl Iterator<Item = &'t str>,
    limit: u64,
) -> Result<(u64, Option<u8>, u64)> {
    let align = 1_u64
        .checked_shl(u32::try_from(unsigned(first)?).map_err(|_| Error("alignment too large"))?)
        .ok_or(Error("alignment too large"))?;
    if align > limit {
        return Err(Error("alignment too large"));
    }
    let (fill, max) = (parts.next(), parts.next());
    if fill == Some("") && max.is_none() {
        return Err(Error("missing alignment fill"));
    }
    let fill = fill
        .filter(|fill| !fill.is_empty())
        .map(|fill| {
            u8::try_from(unsigned(fill)?).map_err(|_| Error("alignment fill exceeds one byte"))
        })
        .transpose()?;
    let max = match max.map(unsigned).transpose()? {
        | Some(0) => return Err(Error("unsatisfiable alignment maximum")),
        | Some(max) if max < align => max,
        | _ => align,
    };
    Ok((align, fill, max))
}

pub(super) fn split(text: &str) -> impl Iterator<Item = &str> {
    let mut quoted = false;
    let mut depth = 0_u32;
    text.split(move |ch| {
        match ch {
            | '"' => quoted = !quoted,
            | '(' if !quoted => depth += 1,
            | ')' if !quoted => depth = depth.saturating_sub(1),
            | _ => {},
        }
        ch == ',' && !quoted && depth == 0
    })
    .map(str::trim)
}

pub(super) fn unquote(text: &str) -> &str {
    text.strip_prefix('"')
        .and_then(|s| s.strip_suffix('"'))
        .unwrap_or(text)
}

pub(super) fn unsigned(text: &str) -> Result<u64> {
    if let Some(hex) = text.strip_prefix("0x") {
        u64::from_str_radix(hex, 16)
    } else {
        text.parse()
    }
    .map_err(|_| Error("invalid integer"))
}

pub(super) fn number(text: &str) -> Result<i64> {
    if let Some(negative) = text.strip_prefix('-') {
        let magnitude = unsigned(negative)?;
        if magnitude > 1_u64 << 63 {
            return Err(Error("negative integer exceeds 64 bits"));
        }
        Ok((magnitude as i64).wrapping_neg())
    } else {
        Ok(unsigned(text)? as i64)
    }
}

pub(super) struct Expression<'a> {
    pub(super) symbol:   Option<&'a str>,
    pub(super) subtract: Option<&'a str>,
    pub(super) addend:   i64,
}

pub(super) fn expression(text: &str) -> Result<Expression<'_>> {
    if let Ok(value) = number(text) {
        return Ok(Expression {
            symbol:   None,
            subtract: None,
            addend:   value,
        });
    }
    let mut quoted = false;
    let mut end = text.len();
    let mut addend = 0;
    let mut subtract = None;
    for (at, ch) in text.char_indices() {
        if ch == '"' {
            quoted = !quoted;
        }
        if at != 0
            && !quoted
            && matches!(ch, '+' | '-')
            && let Ok(value) = number(text[at..].trim_start_matches('+'))
        {
            end = at;
            addend = value;
            break;
        }
    }
    let base = &text[..end];
    quoted = false;
    let mut symbol = base;
    for (at, ch) in base.char_indices() {
        if ch == '"' {
            quoted = !quoted;
        }
        if ch == '-' && !quoted {
            symbol = &base[..at];
            subtract = Some(unquote(&base[at + 1..]));
            break;
        }
    }
    if symbol.is_empty() {
        return Err(Error("invalid symbol expression"));
    }
    symbol_name(symbol)?;
    if let Some(base) = subtract {
        symbol_name(base)?;
    }
    Ok(Expression {
        symbol: Some(unquote(symbol)),
        subtract,
        addend,
    })
}

pub(super) fn assignment(line: &str) -> Option<(&str, &str)> {
    let mut quoted = false;
    for (at, ch) in line.char_indices() {
        if ch == '"' {
            quoted = !quoted;
        }
        if ch == '=' && !quoted {
            return Some((line[..at].trim(), line[at + 1..].trim()));
        }
    }
    None
}

// GNU/LLVM ELF section-name defaults apply even with an explicit flag string.
fn section_defaults(name: &str) -> (u32, u64) {
    let family =
        |stem: &str| name == stem || name.strip_prefix(stem).is_some_and(|s| s.starts_with('.'));
    if family(".text") || matches!(name, ".init" | ".fini") {
        (1, 6)
    } else if family(".bss") {
        (8, 3)
    } else if family(".tbss") {
        (8, 0x403)
    } else if family(".tdata") {
        (1, 0x403)
    } else if family(".data") || name == ".data1" {
        (1, 3)
    } else if family(".rodata") || matches!(name, ".rodata1" | ".gcc_except_table") {
        (1, 2)
    } else if family(".init_array") {
        (14, 3)
    } else if family(".fini_array") {
        (15, 3)
    } else if family(".preinit_array") {
        (16, 3)
    } else if name == ".eh_frame" {
        (0x7000_0001, 2)
    } else if name.starts_with(".note") {
        (7, 0)
    } else {
        (1, 0)
    }
}

pub(super) fn symbol_name(name: &str) -> Result<()> {
    if name.starts_with('"')
        && name.ends_with('"')
        && name.len() > 2
        && !name[1..name.len() - 1]
            .bytes()
            .any(|b| matches!(b, b'"' | b'\\'))
    {
        return Ok(());
    }
    if name.is_empty()
        || name == "."
        || name.bytes().next().is_some_and(|b| b.is_ascii_digit())
        || !name
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'_' | b'.' | b'$'))
    {
        return Err(Error("unsupported symbol expression or relocation suffix"));
    }
    Ok(())
}

fn directive_operands(name: &str, args: &str) -> Result<()> {
    let count = if args.is_empty() {
        0
    } else {
        split(args).count()
    };
    let valid = match name {
        | ".text"
        | ".data"
        | ".bss"
        | ".cfi_startproc"
        | ".cfi_endproc"
        | ".cfi_remember_state"
        | ".cfi_restore_state" => count == 0,
        | ".globl"
        | ".weak"
        | ".hidden"
        | ".protected"
        | ".zero"
        | ".cfi_def_cfa_offset"
        | ".cfi_def_cfa_register" => count == 1,
        | ".size" | ".type" | ".cfi_offset" | ".cfi_def_cfa" => count == 2,
        | ".comm" => count == 3,
        | ".p2align" => (1..=3).contains(&count),
        | ".section" => (1..=5).contains(&count),
        | ".byte" | ".short" | ".long" | ".quad" => count > 0,
        | name if name.starts_with(".cfi_") => return Err(Error("unknown CFI directive")),
        | _ => true,
    };
    if valid {
        Ok(())
    } else {
        Err(Error("unsupported directive operands"))
    }
}
